                    return 0;
                }
                D[num] = i;
                num++;
            }
            if (!is_in(q, D, num))  // if divisor was not already stored
            {
                if (num >= MAX_LENGTH)
                {
                    // Array full, return what we have
                    *out_count = num;
                    return 0;
                }
                D[num] = q;
                num++;
            }
        }
